//! Curated model catalog, generated by `scripts/stt-catalog.mjs`.

use std::sync::OnceLock;

use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Model {
    pub id: String,
    pub name: String,
    pub role: String,
    pub repository: String,
    pub revision: String,
    pub filename: String,
    pub size: u64,
    pub sha256: String,
    pub license: String,
    pub languages: Vec<String>,
    pub streaming: bool,
    pub translate: bool,
    pub language_detection: bool,
    #[serde(default)]
    pub error_pl: Option<f64>,
    #[serde(default)]
    pub error_en: Option<f64>,
    #[serde(default)]
    pub cpu_seconds_per30s: Option<f64>,
    #[serde(default)]
    pub gpu_seconds_per30s: Option<f64>,
}

static MODELS: OnceLock<Vec<Model>> = OnceLock::new();

pub fn models() -> &'static [Model] {
    MODELS.get_or_init(|| {
        serde_json::from_str(include_str!("../catalog.json")).expect("catalog.json is valid")
    })
}

pub fn find(id: &str) -> Option<&'static Model> {
    models().iter().find(|m| m.id == id)
}

pub fn vad() -> &'static Model {
    models()
        .iter()
        .find(|m| m.role == "vad")
        .expect("catalog has a VAD model")
}

pub fn default_model(ui_language: &str) -> &'static Model {
    let id = if ui_language == "en" {
        "parakeet-unified-en-0.6b"
    } else {
        "parakeet-ultra"
    };
    find(id).expect("default model is in the catalog")
}

#[cfg(test)]
mod tests {
    use super::*;

    fn hex(s: &str, len: usize) -> bool {
        s.len() == len && s.bytes().all(|b| matches!(b, b'0'..=b'9' | b'a'..=b'f'))
    }

    #[test]
    fn catalog_is_well_formed() {
        assert!(!models().is_empty());
        let mut ids: Vec<_> = models().iter().map(|m| m.id.as_str()).collect();
        ids.sort_unstable();
        ids.dedup();
        assert_eq!(ids.len(), models().len());
        assert_eq!(models().iter().filter(|m| m.role == "vad").count(), 1);
        for m in models() {
            assert!(hex(&m.revision, 40), "{}", m.id);
            assert!(hex(&m.sha256, 64), "{}", m.id);
            assert!(m.size > 0);
            assert!(!m.filename.contains(['/', '\\']) && m.filename.ends_with(".gguf"));
            assert!(["apache-2.0", "mit", "cc-by-4.0"].contains(&m.license.as_str()));
            assert!(m.role == "vad" || m.cpu_seconds_per30s.is_some());
        }
    }

    #[test]
    fn defaults_follow_language() {
        assert_eq!(default_model("en").id, "parakeet-unified-en-0.6b");
        assert_eq!(default_model("pl").id, "parakeet-ultra");
        assert_eq!(vad().id, "silero-vad-v6.2");
    }
}
